def solve():
    import numpy as np
    from scipy.optimize import minimize

    def get_sum_y(x0, choices):
        x = [x0]
        y = []
        for c in choices:
            if c == 1:
                y.append(x[-1])
                x.append(4 * x[-1]**2)
            else:
                y.append(1/4 - x[-1])
                x.append(x[-1] / 2)

        if x[-1] > x0:
            return 1e9 # Penalty
        return -sum(y)

    best_s = -1e9
    for n in range(1, 6):
        best_s_n = -1e9
        from itertools import product
        for choices in product([1, 2], repeat=n):
            def objective(x0):
                x = [x0]
                y = []
                for c in choices:
                    if c == 1:
                        y.append(x[-1])
                        x.append(4 * x[-1]**2)
                    else:
                        y.append(1/4 - x[-1])
                        x.append(x[-1] / 2)
                if x[-1] > x0:
                    return 1e9
                return -sum(y)

            # Try several starting points for x0
            for start_x0 in np.linspace(-1, 1, 20):
                res = minimize(objective, start_x0)
                if res.success:
                    best_s_n = max(best_s_n, -res.fun)
